style.css:
@-moz-document domain("youtube.com") {
body, ytd-app {
    background-color: red !important;
    color: #e0e0e0 !important;
    font-family: "Fira Code", Roboto, Arial, sans-serif !important;
  }

  /* Video title and text */
  h1, h2, h3, h4, h5, h6, yt-formatted-string, span, a {
    color: #e0e0e0 !important;
  }

  /* Video player background */
  #player-container, ytd-player {
    background-color: #000 !important;
  }

  /* Sidebar and top bar */
  #guide, #masthead-container {
    background-color: #1e1e1e !important;
  }

  /* Comments section */
  #comments {
    background-color: #181818 !important;
    color: #ccc !important;
  }

  /* Search box */
  #search-input input {
    background-color: #2a2a2a !important;
    color: #fff !important;
    border: none !important;
  }

  /* Video suggestions panel */
  ytd-watch-next-secondary-results-renderer {
    background-color: #1a1a1a !important;
  }

  /* Remove some white backgrounds */
  ytd-thumbnail, ytd-rich-grid-media {
    background-color: transparent !important;
  }

  /* Scrollbar styling */
  ::-webkit-scrollbar {
    width: 10px;
  }
  ::-webkit-scrollbar-track {
    background: #121212;
  }
  ::-webkit-scrollbar-thumb {
    background: #444;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: #666;
  }
}
